-- ════════════════════════════════════════════════════════════════════════════
-- Medoria — Migration 45: warehouse lots (batches), expiry dates and quarantine (Health and Beauty, separate)
--
-- GENERATED by scripts/db/gen-warehouse-lots-migration.mjs from one template — edit the template, not this file.
--
-- A LAYER on the warehouse of migration 36; nothing of 36 / 41 is changed except one extra guard trigger on the balances. Stock that has
-- no lot behaves exactly as before. For each house (health_*, beauty_*):
--   *_stock_lots           a batch of ONE product: code, optional expiry date, status active | quarantine | rejected (rejected is final)
--   *_stock_lot_balances   how much of each lot is in each warehouse (the rest of the product's balance there is "no lot")
--   *_stock_movement_lots  which lot a ledger row moved (append-only; the ledger itself is not touched)
--   *_stock_lot_events     history of a lot: created, status changed, expiry changed (who, why, from, to; append-only)
--   *_stock_unusable(location, product)   quantity in quarantined / rejected / expired lots
--   *_stock_lot_post(...)     receive | issue | transfer | adjust of a lot, ONE transaction together with the ledger posting of 36
--   *_stock_lot_reverse(...)  undo a movement with its lots
--   *_stock_lot_update(...)   change a lot's status or expiry date (optimistic version, reason required, events written)
--
-- Rules the database keeps for every path (also the older functions of 36, the count close of 41, a mistaken script):
--   * lot stock in a warehouse never exceeds the product's balance there (the rest is stock without a lot);
--   * stock that is quarantined, rejected or past its expiry date (team date, Asia/Dushanbe) can never be issued, transferred or reserved:
--     usable = quantity - reserved - unusable, and an operation that lowers what is available cannot take it below the unusable quantity;
--   * a lot becoming unusable (quarantine, rejection, an earlier expiry date) is refused while reserved stock would be left without usable stock;
--   * the lot of a movement is recorded with it, so a reversal puts the stock back into the same lot.
--
-- INTERNAL ONLY, like 36: row-level security on, no policy, nothing for anon / authenticated, no direct writes for service_role (the
-- SECURITY DEFINER functions are executable by service_role alone). Nothing is added to the product tables.
--
-- Needs migrations 34, 36 (and 41 for counts). One transaction; idempotent; a self-check at the end aborts (rolls back) on any mismatch.
-- Inert until the application release that uses it is deployed.
-- Rollback (only after the deployed code no longer uses lots, and only when no lot rows are needed):
--   DROP TRIGGER IF EXISTS {h}_stock_balances_lot_guard ON public.{h}_stock_balances;   (for h in health, beauty)
--   DROP FUNCTION IF EXISTS public.{h}_stock_lot_post, public.{h}_stock_lot_reverse, public.{h}_stock_lot_update, public.{h}_stock_unusable CASCADE;
--   DROP TABLE public.{h}_stock_lot_events, public.{h}_stock_movement_lots, public.{h}_stock_lot_balances, public.{h}_stock_lots;
--   DROP FUNCTION IF EXISTS public.{h}_stock_balances_lot_guard(), public.{h}_stock_lot_balances_check(), public.{h}_stock_lots_guard(), public.stock_today();
-- ════════════════════════════════════════════════════════════════════════════

BEGIN;

DO $$
BEGIN
  IF to_regclass('public.health_stock_balances') IS NULL OR to_regclass('public.beauty_stock_balances') IS NULL THEN
    RAISE EXCEPTION 'migration 45 needs migration 36 first (the warehouse tables are missing)';
  END IF;
  IF to_regprocedure('public.stock_require_function()') IS NULL OR to_regprocedure('public.stock_append_only()') IS NULL THEN
    RAISE EXCEPTION 'migration 45 needs the guards of migration 36';
  END IF;
END $$;

-- the team's calendar day (the same one the panel shows): a lot is expired when its expiry date is before today
CREATE OR REPLACE FUNCTION public.stock_today() RETURNS DATE
LANGUAGE sql STABLE AS $$ SELECT (NOW() AT TIME ZONE 'Asia/Dushanbe')::date $$;
REVOKE ALL ON FUNCTION public.stock_today() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.stock_today() TO service_role;

-- ═══ health ═══════════════════════════════════════════════════════════════════════

CREATE TABLE IF NOT EXISTS public.health_stock_lots (
  id            BIGSERIAL PRIMARY KEY,
  product_id    BIGINT NOT NULL,
  lot_code      TEXT NOT NULL CHECK (char_length(lot_code) BETWEEN 1 AND 40 AND lot_code = btrim(lot_code) AND lot_code !~ '[[:cntrl:]]'),
  expiry_date   DATE,
  status        TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'quarantine', 'rejected')),
  created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  created_by    UUID REFERENCES public.operator_users (id),
  created_label TEXT CHECK (created_label IS NULL OR char_length(created_label) <= 80),
  updated_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  version       INT NOT NULL DEFAULT 1
);
CREATE UNIQUE INDEX IF NOT EXISTS health_stock_lots_code ON public.health_stock_lots (product_id, lower(lot_code));
CREATE INDEX IF NOT EXISTS health_stock_lots_expiry ON public.health_stock_lots (expiry_date) WHERE expiry_date IS NOT NULL;
CREATE INDEX IF NOT EXISTS health_stock_lots_status ON public.health_stock_lots (status) WHERE status <> 'active';

CREATE TABLE IF NOT EXISTS public.health_stock_lot_balances (
  lot_id      BIGINT NOT NULL REFERENCES public.health_stock_lots (id) ON DELETE RESTRICT,
  location_id BIGINT NOT NULL REFERENCES public.health_stock_locations (id) ON DELETE RESTRICT,
  quantity    NUMERIC(14,3) NOT NULL DEFAULT 0 CHECK (quantity >= 0),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (lot_id, location_id)
);
CREATE INDEX IF NOT EXISTS health_stock_lot_balances_location ON public.health_stock_lot_balances (location_id);

CREATE TABLE IF NOT EXISTS public.health_stock_movement_lots (
  movement_id BIGINT PRIMARY KEY REFERENCES public.health_stock_movements (id) ON DELETE RESTRICT,
  lot_id      BIGINT NOT NULL REFERENCES public.health_stock_lots (id) ON DELETE RESTRICT,
  delta       NUMERIC(14,3) NOT NULL CHECK (delta <> 0)
);
CREATE INDEX IF NOT EXISTS health_stock_movement_lots_lot ON public.health_stock_movement_lots (lot_id);

CREATE TABLE IF NOT EXISTS public.health_stock_lot_events (
  id            BIGSERIAL PRIMARY KEY,
  lot_id        BIGINT NOT NULL REFERENCES public.health_stock_lots (id) ON DELETE RESTRICT,
  kind          TEXT NOT NULL CHECK (kind IN ('create', 'status', 'expiry')),
  from_value    TEXT CHECK (from_value IS NULL OR char_length(from_value) <= 40),
  to_value      TEXT CHECK (to_value IS NULL OR char_length(to_value) <= 40),
  reason        TEXT CHECK (reason IS NULL OR char_length(reason) <= 300),
  actor_user_id UUID REFERENCES public.operator_users (id),
  actor_label   TEXT CHECK (actor_label IS NULL OR char_length(actor_label) <= 80),
  request_id    TEXT CHECK (request_id IS NULL OR char_length(request_id) <= 80),
  created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS health_stock_lot_events_lot ON public.health_stock_lot_events (lot_id, id);

-- guards: written only by the functions below; a lot's identity never changes; links and events are append-only
CREATE OR REPLACE FUNCTION public.health_stock_lots_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'stock:never_deleted' USING ERRCODE = 'P0001'; END IF;
  IF current_setting('medoria.stock_write', true) IS DISTINCT FROM 'on' THEN RAISE EXCEPTION 'stock:write_only_through_functions' USING ERRCODE = 'P0001'; END IF;
  IF TG_OP = 'UPDATE' AND (NEW.id, NEW.product_id, NEW.lot_code, NEW.created_at, NEW.created_by) IS DISTINCT FROM (OLD.id, OLD.product_id, OLD.lot_code, OLD.created_at, OLD.created_by) THEN
    RAISE EXCEPTION 'stock:lot_identity_is_fixed' USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS health_stock_lots_guard ON public.health_stock_lots;
CREATE TRIGGER health_stock_lots_guard BEFORE INSERT OR UPDATE OR DELETE ON public.health_stock_lots FOR EACH ROW EXECUTE FUNCTION public.health_stock_lots_guard();

DROP TRIGGER IF EXISTS health_stock_lot_balances_guard ON public.health_stock_lot_balances;
CREATE TRIGGER health_stock_lot_balances_guard BEFORE INSERT OR UPDATE OR DELETE ON public.health_stock_lot_balances FOR EACH ROW EXECUTE FUNCTION public.stock_require_function();
DROP TRIGGER IF EXISTS health_stock_movement_lots_insert_guard ON public.health_stock_movement_lots;
CREATE TRIGGER health_stock_movement_lots_insert_guard BEFORE INSERT ON public.health_stock_movement_lots FOR EACH ROW EXECUTE FUNCTION public.stock_require_function();
DROP TRIGGER IF EXISTS health_stock_movement_lots_append_only ON public.health_stock_movement_lots;
CREATE TRIGGER health_stock_movement_lots_append_only BEFORE UPDATE OR DELETE ON public.health_stock_movement_lots FOR EACH ROW EXECUTE FUNCTION public.stock_append_only();
DROP TRIGGER IF EXISTS health_stock_movement_lots_no_truncate ON public.health_stock_movement_lots;
CREATE TRIGGER health_stock_movement_lots_no_truncate BEFORE TRUNCATE ON public.health_stock_movement_lots FOR EACH STATEMENT EXECUTE FUNCTION public.stock_append_only();
DROP TRIGGER IF EXISTS health_stock_lot_events_insert_guard ON public.health_stock_lot_events;
CREATE TRIGGER health_stock_lot_events_insert_guard BEFORE INSERT ON public.health_stock_lot_events FOR EACH ROW EXECUTE FUNCTION public.stock_require_function();
DROP TRIGGER IF EXISTS health_stock_lot_events_append_only ON public.health_stock_lot_events;
CREATE TRIGGER health_stock_lot_events_append_only BEFORE UPDATE OR DELETE ON public.health_stock_lot_events FOR EACH ROW EXECUTE FUNCTION public.stock_append_only();
DROP TRIGGER IF EXISTS health_stock_lot_events_no_truncate ON public.health_stock_lot_events;
CREATE TRIGGER health_stock_lot_events_no_truncate BEFORE TRUNCATE ON public.health_stock_lot_events FOR EACH STATEMENT EXECUTE FUNCTION public.stock_append_only();

-- quantity of a product in a warehouse that cannot be used: quarantined, rejected or past its expiry date
CREATE OR REPLACE FUNCTION public.health_stock_unusable(p_location BIGINT, p_product BIGINT) RETURNS NUMERIC
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
  SELECT COALESCE(sum(b.quantity), 0)
    FROM public.health_stock_lot_balances b JOIN public.health_stock_lots l ON l.id = b.lot_id
   WHERE b.location_id = p_location AND l.product_id = p_product
     AND (l.status <> 'active' OR (l.expiry_date IS NOT NULL AND l.expiry_date < public.stock_today()))
$$;

-- the two invariants, for EVERY path that changes a balance (the functions of 36, the count close of 41, a script run as the owner)
CREATE OR REPLACE FUNCTION public.health_stock_balances_lot_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE v_lots NUMERIC; v_unusable NUMERIC;
BEGIN
  IF NEW.quantity = OLD.quantity AND NEW.reserved = OLD.reserved THEN RETURN NEW; END IF;
  SELECT COALESCE(sum(b.quantity), 0) INTO v_lots
    FROM public.health_stock_lot_balances b JOIN public.health_stock_lots l ON l.id = b.lot_id
   WHERE b.location_id = NEW.location_id AND l.product_id = NEW.product_id;
  -- what is available shrinks: it can never go below the unusable quantity (the message says how much IS usable)
  IF (NEW.quantity - NEW.reserved) < (OLD.quantity - OLD.reserved) THEN
    v_unusable := public.health_stock_unusable(NEW.location_id, NEW.product_id);
    IF (NEW.quantity - NEW.reserved) < v_unusable THEN
      RAISE EXCEPTION 'stock:insufficient_stock' USING ERRCODE = 'P0001', DETAIL = 'available=' || greatest(OLD.quantity - OLD.reserved - v_unusable, 0)::TEXT;
    END IF;
  END IF;
  -- stock kept in lots is taken out through its lot, never through "stock without a lot"
  IF NEW.quantity < v_lots THEN
    RAISE EXCEPTION 'stock:lot_stock_protected' USING ERRCODE = 'P0001', DETAIL = 'lotless=' || greatest(OLD.quantity - v_lots, 0)::TEXT;
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS health_stock_balances_lot_guard ON public.health_stock_balances;
CREATE TRIGGER health_stock_balances_lot_guard BEFORE UPDATE ON public.health_stock_balances FOR EACH ROW EXECUTE FUNCTION public.health_stock_balances_lot_guard();

CREATE OR REPLACE FUNCTION public.health_stock_lot_balances_check() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE v_pid BIGINT; v_sum NUMERIC; v_qty NUMERIC;
BEGIN
  SELECT product_id INTO v_pid FROM public.health_stock_lots WHERE id = NEW.lot_id;
  SELECT COALESCE(sum(b.quantity), 0) INTO v_sum
    FROM public.health_stock_lot_balances b JOIN public.health_stock_lots l ON l.id = b.lot_id
   WHERE b.location_id = NEW.location_id AND l.product_id = v_pid;
  SELECT quantity INTO v_qty FROM public.health_stock_balances WHERE location_id = NEW.location_id AND product_id = v_pid;
  IF v_qty IS NULL OR v_sum > v_qty THEN RAISE EXCEPTION 'stock:lot_stock_protected' USING ERRCODE = 'P0001'; END IF;
  RETURN NULL;
END $$;
DROP TRIGGER IF EXISTS health_stock_lot_balances_check ON public.health_stock_lot_balances;
CREATE TRIGGER health_stock_lot_balances_check AFTER INSERT OR UPDATE ON public.health_stock_lot_balances FOR EACH ROW EXECUTE FUNCTION public.health_stock_lot_balances_check();

-- receive | issue | transfer | adjust of a lot, in the SAME transaction as the ledger posting of migration 36.
--   receive: p_lot_code names the lot (created with p_expiry / p_lot_status 'active' | 'quarantine' when new; the same code again must agree on the expiry)
--   issue | transfer | adjust: p_lot_id names the lot (issue and transfer need a usable lot: active and not expired); NULL = stock without a lot
CREATE OR REPLACE FUNCTION public.health_stock_lot_post(
  p_key TEXT, p_kind TEXT, p_product BIGINT, p_location BIGINT, p_to_location BIGINT, p_qty NUMERIC,
  p_reason TEXT, p_reference TEXT, p_reservation BIGINT, p_actor UUID, p_actor_label TEXT, p_request TEXT,
  p_lot_id BIGINT, p_lot_code TEXT, p_expiry DATE, p_lot_status TEXT
) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $fn$
DECLARE
  v_code TEXT := NULLIF(btrim(COALESCE(p_lot_code, '')), '');
  v_lot RECORD; v_lot_id BIGINT := NULL; v_first RECORD; v_prev BIGINT; v_res JSONB; v_ids JSONB;
  v_new BOOLEAN := FALSE; v_delta NUMERIC; v_cur NUMERIC;
BEGIN
  PERFORM set_config('medoria.stock_write', 'on', true);
  IF p_key IS NULL OR char_length(p_key) NOT BETWEEN 8 AND 80 THEN RAISE EXCEPTION 'stock:bad_key' USING ERRCODE = 'P0001'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('health_stock:' || p_key, 0));
  IF p_kind NOT IN ('receive', 'issue', 'transfer', 'adjust') THEN RAISE EXCEPTION 'stock:bad_kind' USING ERRCODE = 'P0001'; END IF;
  IF p_product IS NULL OR p_product <= 0 THEN RAISE EXCEPTION 'stock:bad_product' USING ERRCODE = 'P0001'; END IF;
  IF p_qty IS NULL OR p_qty = 0 OR p_qty <> round(p_qty, 3) OR abs(p_qty) > 99999999 OR (p_kind <> 'adjust' AND p_qty < 0) THEN
    RAISE EXCEPTION 'stock:bad_quantity' USING ERRCODE = 'P0001';
  END IF;
  IF (p_lot_id IS NOT NULL AND v_code IS NOT NULL) OR (v_code IS NOT NULL AND p_kind <> 'receive') OR (p_kind = 'receive' AND p_lot_id IS NOT NULL)
     OR ((p_expiry IS NOT NULL OR p_lot_status IS NOT NULL) AND v_code IS NULL) OR (p_lot_status IS NOT NULL AND p_lot_status NOT IN ('active', 'quarantine')) THEN
    RAISE EXCEPTION 'stock:bad_lot' USING ERRCODE = 'P0001';
  END IF;
  v_delta := CASE p_kind WHEN 'receive' THEN p_qty WHEN 'adjust' THEN p_qty ELSE -p_qty END;

  -- the same request again: answer it again, change nothing (a different lot under the same key is refused)
  SELECT * INTO v_first FROM public.health_stock_movements WHERE idempotency_key = p_key AND leg = 0;
  IF FOUND THEN
    SELECT lot_id INTO v_prev FROM public.health_stock_movement_lots WHERE movement_id = v_first.id;
    IF v_code IS NOT NULL THEN
      SELECT id INTO v_lot_id FROM public.health_stock_lots WHERE product_id = p_product AND lower(lot_code) = lower(v_code);
    ELSE
      v_lot_id := p_lot_id;
    END IF;
    IF v_prev IS DISTINCT FROM v_lot_id THEN RAISE EXCEPTION 'stock:idempotency_key_reused' USING ERRCODE = 'P0001'; END IF;
    RETURN public.health_stock_post(p_key, p_kind, p_product, p_location, p_to_location, p_qty, p_reason, p_reference, p_reservation, p_actor, p_actor_label, p_request)
           || jsonb_build_object('lot_id', v_prev);
  END IF;

  PERFORM 1 FROM public.products WHERE id = p_product;
  IF NOT FOUND THEN RAISE EXCEPTION 'stock:unknown_product' USING ERRCODE = 'P0001'; END IF;

  IF v_code IS NOT NULL THEN
    SELECT * INTO v_lot FROM public.health_stock_lots WHERE product_id = p_product AND lower(lot_code) = lower(v_code) FOR UPDATE;
    IF FOUND THEN
      IF v_lot.status = 'rejected' THEN RAISE EXCEPTION 'stock:lot_rejected' USING ERRCODE = 'P0001'; END IF;
      IF p_expiry IS NOT NULL AND v_lot.expiry_date IS DISTINCT FROM p_expiry THEN RAISE EXCEPTION 'stock:lot_expiry_mismatch' USING ERRCODE = 'P0001'; END IF;
      v_lot_id := v_lot.id;
    ELSE
      INSERT INTO public.health_stock_lots (product_id, lot_code, expiry_date, status, created_by, created_label)
      VALUES (p_product, v_code, p_expiry, COALESCE(p_lot_status, 'active'), p_actor, p_actor_label)
      RETURNING * INTO v_lot;
      v_lot_id := v_lot.id; v_new := TRUE;
      INSERT INTO public.health_stock_lot_events (lot_id, kind, to_value, reason, actor_user_id, actor_label, request_id)
      VALUES (v_lot_id, 'create', v_lot.status, NULLIF(btrim(p_reason), ''), p_actor, p_actor_label, p_request);
    END IF;
  ELSIF p_lot_id IS NOT NULL THEN
    SELECT * INTO v_lot FROM public.health_stock_lots WHERE id = p_lot_id FOR UPDATE;
    IF NOT FOUND OR v_lot.product_id <> p_product THEN RAISE EXCEPTION 'stock:unknown_lot' USING ERRCODE = 'P0001'; END IF;
    IF p_kind IN ('issue', 'transfer') AND (v_lot.status <> 'active' OR (v_lot.expiry_date IS NOT NULL AND v_lot.expiry_date < public.stock_today())) THEN
      RAISE EXCEPTION 'stock:lot_not_usable' USING ERRCODE = 'P0001';
    END IF;
    v_lot_id := v_lot.id;
  END IF;

  -- stock leaving a lot is taken from the lot BEFORE the ledger posting (the guard of the balance then sees the smaller lot stock)
  IF v_lot_id IS NOT NULL AND v_delta < 0 THEN
    UPDATE public.health_stock_lot_balances SET quantity = quantity - abs(v_delta), updated_at = NOW()
     WHERE lot_id = v_lot_id AND location_id = p_location AND quantity >= abs(v_delta);
    IF NOT FOUND THEN
      SELECT quantity INTO v_cur FROM public.health_stock_lot_balances WHERE lot_id = v_lot_id AND location_id = p_location;
      RAISE EXCEPTION 'stock:insufficient_lot_stock' USING ERRCODE = 'P0001', DETAIL = 'available=' || COALESCE(v_cur, 0)::TEXT;
    END IF;
  END IF;

  v_res := public.health_stock_post(p_key, p_kind, p_product, p_location, p_to_location, p_qty, p_reason, p_reference, p_reservation, p_actor, p_actor_label, p_request);

  -- stock arriving in a lot is added AFTER the ledger posting
  IF v_lot_id IS NOT NULL AND (v_delta > 0 OR p_kind = 'transfer') THEN
    INSERT INTO public.health_stock_lot_balances (lot_id, location_id, quantity)
    VALUES (v_lot_id, CASE WHEN p_kind = 'transfer' THEN p_to_location ELSE p_location END, abs(v_delta))
    ON CONFLICT (lot_id, location_id) DO UPDATE SET quantity = public.health_stock_lot_balances.quantity + EXCLUDED.quantity, updated_at = NOW();
  END IF;

  v_ids := v_res -> 'movement_ids';
  IF v_lot_id IS NOT NULL THEN
    INSERT INTO public.health_stock_movement_lots (movement_id, lot_id, delta) VALUES ((v_ids ->> 0)::BIGINT, v_lot_id, v_delta);
    IF p_kind = 'transfer' THEN
      INSERT INTO public.health_stock_movement_lots (movement_id, lot_id, delta) VALUES ((v_ids ->> 1)::BIGINT, v_lot_id, p_qty);
    END IF;
  END IF;
  RETURN v_res || jsonb_build_object('lot_id', v_lot_id, 'lot_created', v_new);
END $fn$;

-- undo a movement with its lots: the stock goes back into (or out of) the same lot
CREATE OR REPLACE FUNCTION public.health_stock_lot_reverse(
  p_key TEXT, p_movement BIGINT, p_reason TEXT, p_actor UUID, p_actor_label TEXT, p_request TEXT
) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $fn$
DECLARE
  v_orig RECORD; v_link RECORD; v_res JSONB; v_cur NUMERIC;
BEGIN
  PERFORM set_config('medoria.stock_write', 'on', true);
  IF p_key IS NULL OR char_length(p_key) NOT BETWEEN 8 AND 80 THEN RAISE EXCEPTION 'stock:bad_key' USING ERRCODE = 'P0001'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('health_stock:' || p_key, 0));
  SELECT * INTO v_orig FROM public.health_stock_movements WHERE id = p_movement;
  IF NOT FOUND THEN RAISE EXCEPTION 'stock:unknown_movement' USING ERRCODE = 'P0001'; END IF;
  IF EXISTS (SELECT 1 FROM public.health_stock_movements WHERE idempotency_key = p_key AND leg = 0) THEN
    RETURN public.health_stock_reverse(p_key, p_movement, p_reason, p_actor, p_actor_label, p_request);
  END IF;

  -- the refusals of the ledger function come first, so the answer does not depend on the state of the lots
  IF char_length(btrim(COALESCE(p_reason, ''))) < 3 THEN RAISE EXCEPTION 'stock:reason_required' USING ERRCODE = 'P0001'; END IF;
  IF v_orig.kind = 'reversal' THEN RAISE EXCEPTION 'stock:cannot_reverse_a_reversal' USING ERRCODE = 'P0001'; END IF;
  IF EXISTS (SELECT 1 FROM public.health_stock_movements r JOIN public.health_stock_movements o ON o.id = r.reverses_id WHERE o.group_id = v_orig.group_id) THEN
    RAISE EXCEPTION 'stock:already_reversed' USING ERRCODE = 'P0001';
  END IF;

  -- undoing a credit takes stock out of the lot first (it may no longer be there)
  FOR v_link IN
    SELECT m.location_id, l.lot_id, l.delta FROM public.health_stock_movements m JOIN public.health_stock_movement_lots l ON l.movement_id = m.id
     WHERE m.group_id = v_orig.group_id AND l.delta > 0 ORDER BY m.location_id, m.leg
  LOOP
    UPDATE public.health_stock_lot_balances SET quantity = quantity - v_link.delta, updated_at = NOW()
     WHERE lot_id = v_link.lot_id AND location_id = v_link.location_id AND quantity >= v_link.delta;
    IF NOT FOUND THEN
      SELECT quantity INTO v_cur FROM public.health_stock_lot_balances WHERE lot_id = v_link.lot_id AND location_id = v_link.location_id;
      RAISE EXCEPTION 'stock:insufficient_lot_stock' USING ERRCODE = 'P0001', DETAIL = 'available=' || COALESCE(v_cur, 0)::TEXT;
    END IF;
  END LOOP;

  v_res := public.health_stock_reverse(p_key, p_movement, p_reason, p_actor, p_actor_label, p_request);

  -- undoing a debit puts the stock back into the lot
  FOR v_link IN
    SELECT m.location_id, l.lot_id, l.delta FROM public.health_stock_movements m JOIN public.health_stock_movement_lots l ON l.movement_id = m.id
     WHERE m.group_id = v_orig.group_id AND l.delta < 0 ORDER BY m.location_id, m.leg
  LOOP
    INSERT INTO public.health_stock_lot_balances (lot_id, location_id, quantity) VALUES (v_link.lot_id, v_link.location_id, -v_link.delta)
    ON CONFLICT (lot_id, location_id) DO UPDATE SET quantity = public.health_stock_lot_balances.quantity + EXCLUDED.quantity, updated_at = NOW();
  END LOOP;

  -- the reversal rows carry the lot of the row they undo
  INSERT INTO public.health_stock_movement_lots (movement_id, lot_id, delta)
  SELECT r.id, l.lot_id, -l.delta
    FROM public.health_stock_movements r JOIN public.health_stock_movement_lots l ON l.movement_id = r.reverses_id
   WHERE r.id IN (SELECT (jsonb_array_elements_text(v_res -> 'movement_ids'))::BIGINT);
  RETURN v_res;
END $fn$;

-- change a lot's status or expiry date. Reason required; the version the screen showed must still be current; history is written.
CREATE OR REPLACE FUNCTION public.health_stock_lot_update(
  p_lot BIGINT, p_expected_version INT, p_status TEXT, p_set_expiry BOOLEAN, p_expiry DATE, p_reason TEXT, p_actor UUID, p_actor_label TEXT, p_request TEXT
) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $fn$
DECLARE
  v_lot RECORD; v_status TEXT; v_expiry DATE; v_b RECORD; v_was BOOLEAN; v_will BOOLEAN; v_unusable NUMERIC;
BEGIN
  PERFORM set_config('medoria.stock_write', 'on', true);
  SELECT * INTO v_lot FROM public.health_stock_lots WHERE id = p_lot FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'stock:unknown_lot' USING ERRCODE = 'P0001'; END IF;
  IF v_lot.version <> p_expected_version THEN RAISE EXCEPTION 'stock:stale_version' USING ERRCODE = 'P0001'; END IF;
  IF char_length(btrim(COALESCE(p_reason, ''))) < 3 OR char_length(p_reason) > 300 THEN RAISE EXCEPTION 'stock:reason_required' USING ERRCODE = 'P0001'; END IF;
  v_status := COALESCE(p_status, v_lot.status);
  IF v_status NOT IN ('active', 'quarantine', 'rejected') THEN RAISE EXCEPTION 'stock:bad_lot' USING ERRCODE = 'P0001'; END IF;
  v_expiry := CASE WHEN p_set_expiry THEN p_expiry ELSE v_lot.expiry_date END;
  IF v_status = v_lot.status AND v_expiry IS NOT DISTINCT FROM v_lot.expiry_date THEN RAISE EXCEPTION 'stock:nothing_to_change' USING ERRCODE = 'P0001'; END IF;
  IF v_lot.status = 'rejected' THEN RAISE EXCEPTION 'stock:lot_rejected' USING ERRCODE = 'P0001'; END IF;

  v_was := v_lot.status <> 'active' OR (v_lot.expiry_date IS NOT NULL AND v_lot.expiry_date < public.stock_today());
  v_will := v_status <> 'active' OR (v_expiry IS NOT NULL AND v_expiry < public.stock_today());
  IF v_will AND NOT v_was THEN
    -- reserved stock must stay covered by usable stock in every warehouse that holds this lot
    FOR v_b IN
      SELECT b.location_id, b.quantity AS lot_qty, bal.quantity, bal.reserved
        FROM public.health_stock_lot_balances b JOIN public.health_stock_balances bal ON bal.location_id = b.location_id AND bal.product_id = v_lot.product_id
       WHERE b.lot_id = p_lot AND b.quantity > 0 ORDER BY b.location_id FOR UPDATE OF bal
    LOOP
      v_unusable := public.health_stock_unusable(v_b.location_id, v_lot.product_id) + v_b.lot_qty;
      IF v_b.quantity - v_b.reserved < v_unusable THEN
        RAISE EXCEPTION 'stock:reserved_stock_in_lot' USING ERRCODE = 'P0001', DETAIL = 'available=' || greatest(v_b.quantity - v_b.reserved - (v_unusable - v_b.lot_qty), 0)::TEXT;
      END IF;
    END LOOP;
  END IF;

  UPDATE public.health_stock_lots SET status = v_status, expiry_date = v_expiry, version = version + 1, updated_at = NOW() WHERE id = p_lot;
  IF v_status <> v_lot.status THEN
    INSERT INTO public.health_stock_lot_events (lot_id, kind, from_value, to_value, reason, actor_user_id, actor_label, request_id)
    VALUES (p_lot, 'status', v_lot.status, v_status, btrim(p_reason), p_actor, p_actor_label, p_request);
  END IF;
  IF v_expiry IS DISTINCT FROM v_lot.expiry_date THEN
    INSERT INTO public.health_stock_lot_events (lot_id, kind, from_value, to_value, reason, actor_user_id, actor_label, request_id)
    VALUES (p_lot, 'expiry', v_lot.expiry_date::TEXT, v_expiry::TEXT, btrim(p_reason), p_actor, p_actor_label, p_request);
  END IF;
  RETURN jsonb_build_object('ok', TRUE, 'lot_id', p_lot, 'version', v_lot.version + 1);
END $fn$;

-- private: RLS on, no policy, nothing for anon / authenticated; service_role reads; every write goes through the functions
ALTER TABLE public.health_stock_lots ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.health_stock_lot_balances ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.health_stock_movement_lots ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.health_stock_lot_events ENABLE ROW LEVEL SECURITY;
DO $$
DECLARE p record;
BEGIN
  FOR p IN SELECT policyname, tablename FROM pg_policies WHERE schemaname = 'public' AND tablename IN ('health_stock_lots', 'health_stock_lot_balances', 'health_stock_movement_lots', 'health_stock_lot_events') LOOP
    EXECUTE format('DROP POLICY %I ON public.%I', p.policyname, p.tablename);
  END LOOP;
END $$;
REVOKE ALL ON public.health_stock_lots, public.health_stock_lot_balances, public.health_stock_movement_lots, public.health_stock_lot_events FROM PUBLIC, anon, authenticated;
REVOKE ALL ON public.health_stock_lots, public.health_stock_lot_balances, public.health_stock_movement_lots, public.health_stock_lot_events FROM service_role;
GRANT SELECT ON public.health_stock_lots, public.health_stock_lot_balances, public.health_stock_movement_lots, public.health_stock_lot_events TO service_role;
REVOKE ALL ON FUNCTION public.health_stock_lots_guard(), public.health_stock_balances_lot_guard(), public.health_stock_lot_balances_check() FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.health_stock_unusable(BIGINT, BIGINT) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.health_stock_lot_post(TEXT, TEXT, BIGINT, BIGINT, BIGINT, NUMERIC, TEXT, TEXT, BIGINT, UUID, TEXT, TEXT, BIGINT, TEXT, DATE, TEXT) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.health_stock_lot_reverse(TEXT, BIGINT, TEXT, UUID, TEXT, TEXT) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.health_stock_lot_update(BIGINT, INT, TEXT, BOOLEAN, DATE, TEXT, UUID, TEXT, TEXT) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.health_stock_unusable(BIGINT, BIGINT) TO service_role;
GRANT EXECUTE ON FUNCTION public.health_stock_lot_post(TEXT, TEXT, BIGINT, BIGINT, BIGINT, NUMERIC, TEXT, TEXT, BIGINT, UUID, TEXT, TEXT, BIGINT, TEXT, DATE, TEXT) TO service_role;
GRANT EXECUTE ON FUNCTION public.health_stock_lot_reverse(TEXT, BIGINT, TEXT, UUID, TEXT, TEXT) TO service_role;
GRANT EXECUTE ON FUNCTION public.health_stock_lot_update(BIGINT, INT, TEXT, BOOLEAN, DATE, TEXT, UUID, TEXT, TEXT) TO service_role;

-- ═══ beauty ═══════════════════════════════════════════════════════════════════════

CREATE TABLE IF NOT EXISTS public.beauty_stock_lots (
  id            BIGSERIAL PRIMARY KEY,
  product_id    BIGINT NOT NULL,
  lot_code      TEXT NOT NULL CHECK (char_length(lot_code) BETWEEN 1 AND 40 AND lot_code = btrim(lot_code) AND lot_code !~ '[[:cntrl:]]'),
  expiry_date   DATE,
  status        TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'quarantine', 'rejected')),
  created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  created_by    UUID REFERENCES public.operator_users (id),
  created_label TEXT CHECK (created_label IS NULL OR char_length(created_label) <= 80),
  updated_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  version       INT NOT NULL DEFAULT 1
);
CREATE UNIQUE INDEX IF NOT EXISTS beauty_stock_lots_code ON public.beauty_stock_lots (product_id, lower(lot_code));
CREATE INDEX IF NOT EXISTS beauty_stock_lots_expiry ON public.beauty_stock_lots (expiry_date) WHERE expiry_date IS NOT NULL;
CREATE INDEX IF NOT EXISTS beauty_stock_lots_status ON public.beauty_stock_lots (status) WHERE status <> 'active';

CREATE TABLE IF NOT EXISTS public.beauty_stock_lot_balances (
  lot_id      BIGINT NOT NULL REFERENCES public.beauty_stock_lots (id) ON DELETE RESTRICT,
  location_id BIGINT NOT NULL REFERENCES public.beauty_stock_locations (id) ON DELETE RESTRICT,
  quantity    NUMERIC(14,3) NOT NULL DEFAULT 0 CHECK (quantity >= 0),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (lot_id, location_id)
);
CREATE INDEX IF NOT EXISTS beauty_stock_lot_balances_location ON public.beauty_stock_lot_balances (location_id);

CREATE TABLE IF NOT EXISTS public.beauty_stock_movement_lots (
  movement_id BIGINT PRIMARY KEY REFERENCES public.beauty_stock_movements (id) ON DELETE RESTRICT,
  lot_id      BIGINT NOT NULL REFERENCES public.beauty_stock_lots (id) ON DELETE RESTRICT,
  delta       NUMERIC(14,3) NOT NULL CHECK (delta <> 0)
);
CREATE INDEX IF NOT EXISTS beauty_stock_movement_lots_lot ON public.beauty_stock_movement_lots (lot_id);

CREATE TABLE IF NOT EXISTS public.beauty_stock_lot_events (
  id            BIGSERIAL PRIMARY KEY,
  lot_id        BIGINT NOT NULL REFERENCES public.beauty_stock_lots (id) ON DELETE RESTRICT,
  kind          TEXT NOT NULL CHECK (kind IN ('create', 'status', 'expiry')),
  from_value    TEXT CHECK (from_value IS NULL OR char_length(from_value) <= 40),
  to_value      TEXT CHECK (to_value IS NULL OR char_length(to_value) <= 40),
  reason        TEXT CHECK (reason IS NULL OR char_length(reason) <= 300),
  actor_user_id UUID REFERENCES public.operator_users (id),
  actor_label   TEXT CHECK (actor_label IS NULL OR char_length(actor_label) <= 80),
  request_id    TEXT CHECK (request_id IS NULL OR char_length(request_id) <= 80),
  created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS beauty_stock_lot_events_lot ON public.beauty_stock_lot_events (lot_id, id);

-- guards: written only by the functions below; a lot's identity never changes; links and events are append-only
CREATE OR REPLACE FUNCTION public.beauty_stock_lots_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'stock:never_deleted' USING ERRCODE = 'P0001'; END IF;
  IF current_setting('medoria.stock_write', true) IS DISTINCT FROM 'on' THEN RAISE EXCEPTION 'stock:write_only_through_functions' USING ERRCODE = 'P0001'; END IF;
  IF TG_OP = 'UPDATE' AND (NEW.id, NEW.product_id, NEW.lot_code, NEW.created_at, NEW.created_by) IS DISTINCT FROM (OLD.id, OLD.product_id, OLD.lot_code, OLD.created_at, OLD.created_by) THEN
    RAISE EXCEPTION 'stock:lot_identity_is_fixed' USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS beauty_stock_lots_guard ON public.beauty_stock_lots;
CREATE TRIGGER beauty_stock_lots_guard BEFORE INSERT OR UPDATE OR DELETE ON public.beauty_stock_lots FOR EACH ROW EXECUTE FUNCTION public.beauty_stock_lots_guard();

DROP TRIGGER IF EXISTS beauty_stock_lot_balances_guard ON public.beauty_stock_lot_balances;
CREATE TRIGGER beauty_stock_lot_balances_guard BEFORE INSERT OR UPDATE OR DELETE ON public.beauty_stock_lot_balances FOR EACH ROW EXECUTE FUNCTION public.stock_require_function();
DROP TRIGGER IF EXISTS beauty_stock_movement_lots_insert_guard ON public.beauty_stock_movement_lots;
CREATE TRIGGER beauty_stock_movement_lots_insert_guard BEFORE INSERT ON public.beauty_stock_movement_lots FOR EACH ROW EXECUTE FUNCTION public.stock_require_function();
DROP TRIGGER IF EXISTS beauty_stock_movement_lots_append_only ON public.beauty_stock_movement_lots;
CREATE TRIGGER beauty_stock_movement_lots_append_only BEFORE UPDATE OR DELETE ON public.beauty_stock_movement_lots FOR EACH ROW EXECUTE FUNCTION public.stock_append_only();
DROP TRIGGER IF EXISTS beauty_stock_movement_lots_no_truncate ON public.beauty_stock_movement_lots;
CREATE TRIGGER beauty_stock_movement_lots_no_truncate BEFORE TRUNCATE ON public.beauty_stock_movement_lots FOR EACH STATEMENT EXECUTE FUNCTION public.stock_append_only();
DROP TRIGGER IF EXISTS beauty_stock_lot_events_insert_guard ON public.beauty_stock_lot_events;
CREATE TRIGGER beauty_stock_lot_events_insert_guard BEFORE INSERT ON public.beauty_stock_lot_events FOR EACH ROW EXECUTE FUNCTION public.stock_require_function();
DROP TRIGGER IF EXISTS beauty_stock_lot_events_append_only ON public.beauty_stock_lot_events;
CREATE TRIGGER beauty_stock_lot_events_append_only BEFORE UPDATE OR DELETE ON public.beauty_stock_lot_events FOR EACH ROW EXECUTE FUNCTION public.stock_append_only();
DROP TRIGGER IF EXISTS beauty_stock_lot_events_no_truncate ON public.beauty_stock_lot_events;
CREATE TRIGGER beauty_stock_lot_events_no_truncate BEFORE TRUNCATE ON public.beauty_stock_lot_events FOR EACH STATEMENT EXECUTE FUNCTION public.stock_append_only();

-- quantity of a product in a warehouse that cannot be used: quarantined, rejected or past its expiry date
CREATE OR REPLACE FUNCTION public.beauty_stock_unusable(p_location BIGINT, p_product BIGINT) RETURNS NUMERIC
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
  SELECT COALESCE(sum(b.quantity), 0)
    FROM public.beauty_stock_lot_balances b JOIN public.beauty_stock_lots l ON l.id = b.lot_id
   WHERE b.location_id = p_location AND l.product_id = p_product
     AND (l.status <> 'active' OR (l.expiry_date IS NOT NULL AND l.expiry_date < public.stock_today()))
$$;

-- the two invariants, for EVERY path that changes a balance (the functions of 36, the count close of 41, a script run as the owner)
CREATE OR REPLACE FUNCTION public.beauty_stock_balances_lot_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE v_lots NUMERIC; v_unusable NUMERIC;
BEGIN
  IF NEW.quantity = OLD.quantity AND NEW.reserved = OLD.reserved THEN RETURN NEW; END IF;
  SELECT COALESCE(sum(b.quantity), 0) INTO v_lots
    FROM public.beauty_stock_lot_balances b JOIN public.beauty_stock_lots l ON l.id = b.lot_id
   WHERE b.location_id = NEW.location_id AND l.product_id = NEW.product_id;
  -- what is available shrinks: it can never go below the unusable quantity (the message says how much IS usable)
  IF (NEW.quantity - NEW.reserved) < (OLD.quantity - OLD.reserved) THEN
    v_unusable := public.beauty_stock_unusable(NEW.location_id, NEW.product_id);
    IF (NEW.quantity - NEW.reserved) < v_unusable THEN
      RAISE EXCEPTION 'stock:insufficient_stock' USING ERRCODE = 'P0001', DETAIL = 'available=' || greatest(OLD.quantity - OLD.reserved - v_unusable, 0)::TEXT;
    END IF;
  END IF;
  -- stock kept in lots is taken out through its lot, never through "stock without a lot"
  IF NEW.quantity < v_lots THEN
    RAISE EXCEPTION 'stock:lot_stock_protected' USING ERRCODE = 'P0001', DETAIL = 'lotless=' || greatest(OLD.quantity - v_lots, 0)::TEXT;
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS beauty_stock_balances_lot_guard ON public.beauty_stock_balances;
CREATE TRIGGER beauty_stock_balances_lot_guard BEFORE UPDATE ON public.beauty_stock_balances FOR EACH ROW EXECUTE FUNCTION public.beauty_stock_balances_lot_guard();

CREATE OR REPLACE FUNCTION public.beauty_stock_lot_balances_check() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE v_pid BIGINT; v_sum NUMERIC; v_qty NUMERIC;
BEGIN
  SELECT product_id INTO v_pid FROM public.beauty_stock_lots WHERE id = NEW.lot_id;
  SELECT COALESCE(sum(b.quantity), 0) INTO v_sum
    FROM public.beauty_stock_lot_balances b JOIN public.beauty_stock_lots l ON l.id = b.lot_id
   WHERE b.location_id = NEW.location_id AND l.product_id = v_pid;
  SELECT quantity INTO v_qty FROM public.beauty_stock_balances WHERE location_id = NEW.location_id AND product_id = v_pid;
  IF v_qty IS NULL OR v_sum > v_qty THEN RAISE EXCEPTION 'stock:lot_stock_protected' USING ERRCODE = 'P0001'; END IF;
  RETURN NULL;
END $$;
DROP TRIGGER IF EXISTS beauty_stock_lot_balances_check ON public.beauty_stock_lot_balances;
CREATE TRIGGER beauty_stock_lot_balances_check AFTER INSERT OR UPDATE ON public.beauty_stock_lot_balances FOR EACH ROW EXECUTE FUNCTION public.beauty_stock_lot_balances_check();

-- receive | issue | transfer | adjust of a lot, in the SAME transaction as the ledger posting of migration 36.
--   receive: p_lot_code names the lot (created with p_expiry / p_lot_status 'active' | 'quarantine' when new; the same code again must agree on the expiry)
--   issue | transfer | adjust: p_lot_id names the lot (issue and transfer need a usable lot: active and not expired); NULL = stock without a lot
CREATE OR REPLACE FUNCTION public.beauty_stock_lot_post(
  p_key TEXT, p_kind TEXT, p_product BIGINT, p_location BIGINT, p_to_location BIGINT, p_qty NUMERIC,
  p_reason TEXT, p_reference TEXT, p_reservation BIGINT, p_actor UUID, p_actor_label TEXT, p_request TEXT,
  p_lot_id BIGINT, p_lot_code TEXT, p_expiry DATE, p_lot_status TEXT
) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $fn$
DECLARE
  v_code TEXT := NULLIF(btrim(COALESCE(p_lot_code, '')), '');
  v_lot RECORD; v_lot_id BIGINT := NULL; v_first RECORD; v_prev BIGINT; v_res JSONB; v_ids JSONB;
  v_new BOOLEAN := FALSE; v_delta NUMERIC; v_cur NUMERIC;
BEGIN
  PERFORM set_config('medoria.stock_write', 'on', true);
  IF p_key IS NULL OR char_length(p_key) NOT BETWEEN 8 AND 80 THEN RAISE EXCEPTION 'stock:bad_key' USING ERRCODE = 'P0001'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('beauty_stock:' || p_key, 0));
  IF p_kind NOT IN ('receive', 'issue', 'transfer', 'adjust') THEN RAISE EXCEPTION 'stock:bad_kind' USING ERRCODE = 'P0001'; END IF;
  IF p_product IS NULL OR p_product <= 0 THEN RAISE EXCEPTION 'stock:bad_product' USING ERRCODE = 'P0001'; END IF;
  IF p_qty IS NULL OR p_qty = 0 OR p_qty <> round(p_qty, 3) OR abs(p_qty) > 99999999 OR (p_kind <> 'adjust' AND p_qty < 0) THEN
    RAISE EXCEPTION 'stock:bad_quantity' USING ERRCODE = 'P0001';
  END IF;
  IF (p_lot_id IS NOT NULL AND v_code IS NOT NULL) OR (v_code IS NOT NULL AND p_kind <> 'receive') OR (p_kind = 'receive' AND p_lot_id IS NOT NULL)
     OR ((p_expiry IS NOT NULL OR p_lot_status IS NOT NULL) AND v_code IS NULL) OR (p_lot_status IS NOT NULL AND p_lot_status NOT IN ('active', 'quarantine')) THEN
    RAISE EXCEPTION 'stock:bad_lot' USING ERRCODE = 'P0001';
  END IF;
  v_delta := CASE p_kind WHEN 'receive' THEN p_qty WHEN 'adjust' THEN p_qty ELSE -p_qty END;

  -- the same request again: answer it again, change nothing (a different lot under the same key is refused)
  SELECT * INTO v_first FROM public.beauty_stock_movements WHERE idempotency_key = p_key AND leg = 0;
  IF FOUND THEN
    SELECT lot_id INTO v_prev FROM public.beauty_stock_movement_lots WHERE movement_id = v_first.id;
    IF v_code IS NOT NULL THEN
      SELECT id INTO v_lot_id FROM public.beauty_stock_lots WHERE product_id = p_product AND lower(lot_code) = lower(v_code);
    ELSE
      v_lot_id := p_lot_id;
    END IF;
    IF v_prev IS DISTINCT FROM v_lot_id THEN RAISE EXCEPTION 'stock:idempotency_key_reused' USING ERRCODE = 'P0001'; END IF;
    RETURN public.beauty_stock_post(p_key, p_kind, p_product, p_location, p_to_location, p_qty, p_reason, p_reference, p_reservation, p_actor, p_actor_label, p_request)
           || jsonb_build_object('lot_id', v_prev);
  END IF;

  PERFORM 1 FROM public.beauty_products WHERE id = p_product;
  IF NOT FOUND THEN RAISE EXCEPTION 'stock:unknown_product' USING ERRCODE = 'P0001'; END IF;

  IF v_code IS NOT NULL THEN
    SELECT * INTO v_lot FROM public.beauty_stock_lots WHERE product_id = p_product AND lower(lot_code) = lower(v_code) FOR UPDATE;
    IF FOUND THEN
      IF v_lot.status = 'rejected' THEN RAISE EXCEPTION 'stock:lot_rejected' USING ERRCODE = 'P0001'; END IF;
      IF p_expiry IS NOT NULL AND v_lot.expiry_date IS DISTINCT FROM p_expiry THEN RAISE EXCEPTION 'stock:lot_expiry_mismatch' USING ERRCODE = 'P0001'; END IF;
      v_lot_id := v_lot.id;
    ELSE
      INSERT INTO public.beauty_stock_lots (product_id, lot_code, expiry_date, status, created_by, created_label)
      VALUES (p_product, v_code, p_expiry, COALESCE(p_lot_status, 'active'), p_actor, p_actor_label)
      RETURNING * INTO v_lot;
      v_lot_id := v_lot.id; v_new := TRUE;
      INSERT INTO public.beauty_stock_lot_events (lot_id, kind, to_value, reason, actor_user_id, actor_label, request_id)
      VALUES (v_lot_id, 'create', v_lot.status, NULLIF(btrim(p_reason), ''), p_actor, p_actor_label, p_request);
    END IF;
  ELSIF p_lot_id IS NOT NULL THEN
    SELECT * INTO v_lot FROM public.beauty_stock_lots WHERE id = p_lot_id FOR UPDATE;
    IF NOT FOUND OR v_lot.product_id <> p_product THEN RAISE EXCEPTION 'stock:unknown_lot' USING ERRCODE = 'P0001'; END IF;
    IF p_kind IN ('issue', 'transfer') AND (v_lot.status <> 'active' OR (v_lot.expiry_date IS NOT NULL AND v_lot.expiry_date < public.stock_today())) THEN
      RAISE EXCEPTION 'stock:lot_not_usable' USING ERRCODE = 'P0001';
    END IF;
    v_lot_id := v_lot.id;
  END IF;

  -- stock leaving a lot is taken from the lot BEFORE the ledger posting (the guard of the balance then sees the smaller lot stock)
  IF v_lot_id IS NOT NULL AND v_delta < 0 THEN
    UPDATE public.beauty_stock_lot_balances SET quantity = quantity - abs(v_delta), updated_at = NOW()
     WHERE lot_id = v_lot_id AND location_id = p_location AND quantity >= abs(v_delta);
    IF NOT FOUND THEN
      SELECT quantity INTO v_cur FROM public.beauty_stock_lot_balances WHERE lot_id = v_lot_id AND location_id = p_location;
      RAISE EXCEPTION 'stock:insufficient_lot_stock' USING ERRCODE = 'P0001', DETAIL = 'available=' || COALESCE(v_cur, 0)::TEXT;
    END IF;
  END IF;

  v_res := public.beauty_stock_post(p_key, p_kind, p_product, p_location, p_to_location, p_qty, p_reason, p_reference, p_reservation, p_actor, p_actor_label, p_request);

  -- stock arriving in a lot is added AFTER the ledger posting
  IF v_lot_id IS NOT NULL AND (v_delta > 0 OR p_kind = 'transfer') THEN
    INSERT INTO public.beauty_stock_lot_balances (lot_id, location_id, quantity)
    VALUES (v_lot_id, CASE WHEN p_kind = 'transfer' THEN p_to_location ELSE p_location END, abs(v_delta))
    ON CONFLICT (lot_id, location_id) DO UPDATE SET quantity = public.beauty_stock_lot_balances.quantity + EXCLUDED.quantity, updated_at = NOW();
  END IF;

  v_ids := v_res -> 'movement_ids';
  IF v_lot_id IS NOT NULL THEN
    INSERT INTO public.beauty_stock_movement_lots (movement_id, lot_id, delta) VALUES ((v_ids ->> 0)::BIGINT, v_lot_id, v_delta);
    IF p_kind = 'transfer' THEN
      INSERT INTO public.beauty_stock_movement_lots (movement_id, lot_id, delta) VALUES ((v_ids ->> 1)::BIGINT, v_lot_id, p_qty);
    END IF;
  END IF;
  RETURN v_res || jsonb_build_object('lot_id', v_lot_id, 'lot_created', v_new);
END $fn$;

-- undo a movement with its lots: the stock goes back into (or out of) the same lot
CREATE OR REPLACE FUNCTION public.beauty_stock_lot_reverse(
  p_key TEXT, p_movement BIGINT, p_reason TEXT, p_actor UUID, p_actor_label TEXT, p_request TEXT
) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $fn$
DECLARE
  v_orig RECORD; v_link RECORD; v_res JSONB; v_cur NUMERIC;
BEGIN
  PERFORM set_config('medoria.stock_write', 'on', true);
  IF p_key IS NULL OR char_length(p_key) NOT BETWEEN 8 AND 80 THEN RAISE EXCEPTION 'stock:bad_key' USING ERRCODE = 'P0001'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('beauty_stock:' || p_key, 0));
  SELECT * INTO v_orig FROM public.beauty_stock_movements WHERE id = p_movement;
  IF NOT FOUND THEN RAISE EXCEPTION 'stock:unknown_movement' USING ERRCODE = 'P0001'; END IF;
  IF EXISTS (SELECT 1 FROM public.beauty_stock_movements WHERE idempotency_key = p_key AND leg = 0) THEN
    RETURN public.beauty_stock_reverse(p_key, p_movement, p_reason, p_actor, p_actor_label, p_request);
  END IF;

  -- the refusals of the ledger function come first, so the answer does not depend on the state of the lots
  IF char_length(btrim(COALESCE(p_reason, ''))) < 3 THEN RAISE EXCEPTION 'stock:reason_required' USING ERRCODE = 'P0001'; END IF;
  IF v_orig.kind = 'reversal' THEN RAISE EXCEPTION 'stock:cannot_reverse_a_reversal' USING ERRCODE = 'P0001'; END IF;
  IF EXISTS (SELECT 1 FROM public.beauty_stock_movements r JOIN public.beauty_stock_movements o ON o.id = r.reverses_id WHERE o.group_id = v_orig.group_id) THEN
    RAISE EXCEPTION 'stock:already_reversed' USING ERRCODE = 'P0001';
  END IF;

  -- undoing a credit takes stock out of the lot first (it may no longer be there)
  FOR v_link IN
    SELECT m.location_id, l.lot_id, l.delta FROM public.beauty_stock_movements m JOIN public.beauty_stock_movement_lots l ON l.movement_id = m.id
     WHERE m.group_id = v_orig.group_id AND l.delta > 0 ORDER BY m.location_id, m.leg
  LOOP
    UPDATE public.beauty_stock_lot_balances SET quantity = quantity - v_link.delta, updated_at = NOW()
     WHERE lot_id = v_link.lot_id AND location_id = v_link.location_id AND quantity >= v_link.delta;
    IF NOT FOUND THEN
      SELECT quantity INTO v_cur FROM public.beauty_stock_lot_balances WHERE lot_id = v_link.lot_id AND location_id = v_link.location_id;
      RAISE EXCEPTION 'stock:insufficient_lot_stock' USING ERRCODE = 'P0001', DETAIL = 'available=' || COALESCE(v_cur, 0)::TEXT;
    END IF;
  END LOOP;

  v_res := public.beauty_stock_reverse(p_key, p_movement, p_reason, p_actor, p_actor_label, p_request);

  -- undoing a debit puts the stock back into the lot
  FOR v_link IN
    SELECT m.location_id, l.lot_id, l.delta FROM public.beauty_stock_movements m JOIN public.beauty_stock_movement_lots l ON l.movement_id = m.id
     WHERE m.group_id = v_orig.group_id AND l.delta < 0 ORDER BY m.location_id, m.leg
  LOOP
    INSERT INTO public.beauty_stock_lot_balances (lot_id, location_id, quantity) VALUES (v_link.lot_id, v_link.location_id, -v_link.delta)
    ON CONFLICT (lot_id, location_id) DO UPDATE SET quantity = public.beauty_stock_lot_balances.quantity + EXCLUDED.quantity, updated_at = NOW();
  END LOOP;

  -- the reversal rows carry the lot of the row they undo
  INSERT INTO public.beauty_stock_movement_lots (movement_id, lot_id, delta)
  SELECT r.id, l.lot_id, -l.delta
    FROM public.beauty_stock_movements r JOIN public.beauty_stock_movement_lots l ON l.movement_id = r.reverses_id
   WHERE r.id IN (SELECT (jsonb_array_elements_text(v_res -> 'movement_ids'))::BIGINT);
  RETURN v_res;
END $fn$;

-- change a lot's status or expiry date. Reason required; the version the screen showed must still be current; history is written.
CREATE OR REPLACE FUNCTION public.beauty_stock_lot_update(
  p_lot BIGINT, p_expected_version INT, p_status TEXT, p_set_expiry BOOLEAN, p_expiry DATE, p_reason TEXT, p_actor UUID, p_actor_label TEXT, p_request TEXT
) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $fn$
DECLARE
  v_lot RECORD; v_status TEXT; v_expiry DATE; v_b RECORD; v_was BOOLEAN; v_will BOOLEAN; v_unusable NUMERIC;
BEGIN
  PERFORM set_config('medoria.stock_write', 'on', true);
  SELECT * INTO v_lot FROM public.beauty_stock_lots WHERE id = p_lot FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'stock:unknown_lot' USING ERRCODE = 'P0001'; END IF;
  IF v_lot.version <> p_expected_version THEN RAISE EXCEPTION 'stock:stale_version' USING ERRCODE = 'P0001'; END IF;
  IF char_length(btrim(COALESCE(p_reason, ''))) < 3 OR char_length(p_reason) > 300 THEN RAISE EXCEPTION 'stock:reason_required' USING ERRCODE = 'P0001'; END IF;
  v_status := COALESCE(p_status, v_lot.status);
  IF v_status NOT IN ('active', 'quarantine', 'rejected') THEN RAISE EXCEPTION 'stock:bad_lot' USING ERRCODE = 'P0001'; END IF;
  v_expiry := CASE WHEN p_set_expiry THEN p_expiry ELSE v_lot.expiry_date END;
  IF v_status = v_lot.status AND v_expiry IS NOT DISTINCT FROM v_lot.expiry_date THEN RAISE EXCEPTION 'stock:nothing_to_change' USING ERRCODE = 'P0001'; END IF;
  IF v_lot.status = 'rejected' THEN RAISE EXCEPTION 'stock:lot_rejected' USING ERRCODE = 'P0001'; END IF;

  v_was := v_lot.status <> 'active' OR (v_lot.expiry_date IS NOT NULL AND v_lot.expiry_date < public.stock_today());
  v_will := v_status <> 'active' OR (v_expiry IS NOT NULL AND v_expiry < public.stock_today());
  IF v_will AND NOT v_was THEN
    -- reserved stock must stay covered by usable stock in every warehouse that holds this lot
    FOR v_b IN
      SELECT b.location_id, b.quantity AS lot_qty, bal.quantity, bal.reserved
        FROM public.beauty_stock_lot_balances b JOIN public.beauty_stock_balances bal ON bal.location_id = b.location_id AND bal.product_id = v_lot.product_id
       WHERE b.lot_id = p_lot AND b.quantity > 0 ORDER BY b.location_id FOR UPDATE OF bal
    LOOP
      v_unusable := public.beauty_stock_unusable(v_b.location_id, v_lot.product_id) + v_b.lot_qty;
      IF v_b.quantity - v_b.reserved < v_unusable THEN
        RAISE EXCEPTION 'stock:reserved_stock_in_lot' USING ERRCODE = 'P0001', DETAIL = 'available=' || greatest(v_b.quantity - v_b.reserved - (v_unusable - v_b.lot_qty), 0)::TEXT;
      END IF;
    END LOOP;
  END IF;

  UPDATE public.beauty_stock_lots SET status = v_status, expiry_date = v_expiry, version = version + 1, updated_at = NOW() WHERE id = p_lot;
  IF v_status <> v_lot.status THEN
    INSERT INTO public.beauty_stock_lot_events (lot_id, kind, from_value, to_value, reason, actor_user_id, actor_label, request_id)
    VALUES (p_lot, 'status', v_lot.status, v_status, btrim(p_reason), p_actor, p_actor_label, p_request);
  END IF;
  IF v_expiry IS DISTINCT FROM v_lot.expiry_date THEN
    INSERT INTO public.beauty_stock_lot_events (lot_id, kind, from_value, to_value, reason, actor_user_id, actor_label, request_id)
    VALUES (p_lot, 'expiry', v_lot.expiry_date::TEXT, v_expiry::TEXT, btrim(p_reason), p_actor, p_actor_label, p_request);
  END IF;
  RETURN jsonb_build_object('ok', TRUE, 'lot_id', p_lot, 'version', v_lot.version + 1);
END $fn$;

-- private: RLS on, no policy, nothing for anon / authenticated; service_role reads; every write goes through the functions
ALTER TABLE public.beauty_stock_lots ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.beauty_stock_lot_balances ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.beauty_stock_movement_lots ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.beauty_stock_lot_events ENABLE ROW LEVEL SECURITY;
DO $$
DECLARE p record;
BEGIN
  FOR p IN SELECT policyname, tablename FROM pg_policies WHERE schemaname = 'public' AND tablename IN ('beauty_stock_lots', 'beauty_stock_lot_balances', 'beauty_stock_movement_lots', 'beauty_stock_lot_events') LOOP
    EXECUTE format('DROP POLICY %I ON public.%I', p.policyname, p.tablename);
  END LOOP;
END $$;
REVOKE ALL ON public.beauty_stock_lots, public.beauty_stock_lot_balances, public.beauty_stock_movement_lots, public.beauty_stock_lot_events FROM PUBLIC, anon, authenticated;
REVOKE ALL ON public.beauty_stock_lots, public.beauty_stock_lot_balances, public.beauty_stock_movement_lots, public.beauty_stock_lot_events FROM service_role;
GRANT SELECT ON public.beauty_stock_lots, public.beauty_stock_lot_balances, public.beauty_stock_movement_lots, public.beauty_stock_lot_events TO service_role;
REVOKE ALL ON FUNCTION public.beauty_stock_lots_guard(), public.beauty_stock_balances_lot_guard(), public.beauty_stock_lot_balances_check() FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.beauty_stock_unusable(BIGINT, BIGINT) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.beauty_stock_lot_post(TEXT, TEXT, BIGINT, BIGINT, BIGINT, NUMERIC, TEXT, TEXT, BIGINT, UUID, TEXT, TEXT, BIGINT, TEXT, DATE, TEXT) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.beauty_stock_lot_reverse(TEXT, BIGINT, TEXT, UUID, TEXT, TEXT) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.beauty_stock_lot_update(BIGINT, INT, TEXT, BOOLEAN, DATE, TEXT, UUID, TEXT, TEXT) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.beauty_stock_unusable(BIGINT, BIGINT) TO service_role;
GRANT EXECUTE ON FUNCTION public.beauty_stock_lot_post(TEXT, TEXT, BIGINT, BIGINT, BIGINT, NUMERIC, TEXT, TEXT, BIGINT, UUID, TEXT, TEXT, BIGINT, TEXT, DATE, TEXT) TO service_role;
GRANT EXECUTE ON FUNCTION public.beauty_stock_lot_reverse(TEXT, BIGINT, TEXT, UUID, TEXT, TEXT) TO service_role;
GRANT EXECUTE ON FUNCTION public.beauty_stock_lot_update(BIGINT, INT, TEXT, BOOLEAN, DATE, TEXT, UUID, TEXT, TEXT) TO service_role;

-- self-check
DO $$
DECLARE h TEXT; t TEXT; f TEXT;
BEGIN
  FOREACH h IN ARRAY ARRAY['health', 'beauty'] LOOP
    FOREACH t IN ARRAY ARRAY['stock_lots', 'stock_lot_balances', 'stock_movement_lots', 'stock_lot_events'] LOOP
      IF to_regclass('public.' || h || '_' || t) IS NULL THEN
        RAISE EXCEPTION 'migration 45 self-check failed: % is missing', h || '_' || t;
      END IF;
      IF NOT (SELECT relrowsecurity FROM pg_class WHERE oid = ('public.' || h || '_' || t)::regclass) THEN
        RAISE EXCEPTION 'migration 45 self-check failed: row-level security is off on %', h || '_' || t;
      END IF;
      IF EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = h || '_' || t) THEN
        RAISE EXCEPTION 'migration 45 self-check failed: % has a policy', h || '_' || t;
      END IF;
      IF has_table_privilege('anon', 'public.' || h || '_' || t, 'SELECT') OR has_table_privilege('authenticated', 'public.' || h || '_' || t, 'SELECT')
         OR has_table_privilege('anon', 'public.' || h || '_' || t, 'INSERT') OR has_table_privilege('authenticated', 'public.' || h || '_' || t, 'INSERT') THEN
        RAISE EXCEPTION 'migration 45 self-check failed: anon/authenticated can reach %', h || '_' || t;
      END IF;
      IF NOT has_table_privilege('service_role', 'public.' || h || '_' || t, 'SELECT') THEN
        RAISE EXCEPTION 'migration 45 self-check failed: service_role cannot read %', h || '_' || t;
      END IF;
      IF has_table_privilege('service_role', 'public.' || h || '_' || t, 'INSERT') OR has_table_privilege('service_role', 'public.' || h || '_' || t, 'UPDATE')
         OR has_table_privilege('service_role', 'public.' || h || '_' || t, 'DELETE') THEN
        RAISE EXCEPTION 'migration 45 self-check failed: service_role can write % directly', h || '_' || t;
      END IF;
    END LOOP;
    FOREACH f IN ARRAY ARRAY['stock_lot_post', 'stock_lot_reverse', 'stock_lot_update', 'stock_unusable'] LOOP
      IF NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = h || '_' || f AND pronamespace = 'public'::regnamespace AND prosecdef) THEN
        RAISE EXCEPTION 'migration 45 self-check failed: function % is missing or not SECURITY DEFINER', h || '_' || f;
      END IF;
      IF EXISTS (SELECT 1 FROM pg_proc p WHERE p.proname = h || '_' || f AND p.pronamespace = 'public'::regnamespace
                 AND (has_function_privilege('anon', p.oid, 'EXECUTE') OR has_function_privilege('authenticated', p.oid, 'EXECUTE'))) THEN
        RAISE EXCEPTION 'migration 45 self-check failed: anon/authenticated can execute %', h || '_' || f;
      END IF;
      IF NOT EXISTS (SELECT 1 FROM pg_proc p WHERE p.proname = h || '_' || f AND p.pronamespace = 'public'::regnamespace AND has_function_privilege('service_role', p.oid, 'EXECUTE')) THEN
        RAISE EXCEPTION 'migration 45 self-check failed: service_role cannot execute %', h || '_' || f;
      END IF;
    END LOOP;
    IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid = ('public.' || h || '_stock_balances')::regclass AND tgname = h || '_stock_balances_lot_guard' AND NOT tgisinternal) THEN
      RAISE EXCEPTION 'migration 45 self-check failed: the lot guard of %_stock_balances is missing', h;
    END IF;
  END LOOP;
END $$;

COMMIT;

